pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 val, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(val < type(uint256).max - 1);
        vm.prank(actor);
        try c.SetMinSum(val) {
            assertTrue(c.MinSum() == val);
        } catch {
            assertTrue(false);
        }
    }
}
